-- mistri store layout: branding, sqlite, version 1. Generated by scripts/store-layouts.mjs; never edit by hand.
CREATE TABLE "__mistri_branding_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1)
);
CREATE TABLE "__mistri_branding_value" (
  app TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(app AS BLOB)) <= 128),
  tenant TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(tenant AS BLOB)) <= 128),
  value_json TEXT NOT NULL CHECK (json_valid(value_json) AND length(CAST(value_json AS BLOB)) <= 8192),
  logo_hash TEXT COLLATE BINARY,
  revision INTEGER NOT NULL,
  saved_by TEXT NOT NULL,
  saved_at TEXT NOT NULL,
  PRIMARY KEY (app, tenant)
);
CREATE TABLE "__mistri_branding_logo" (
  app TEXT COLLATE BINARY NOT NULL,
  hash TEXT COLLATE BINARY NOT NULL,
  type TEXT NOT NULL,
  bytes BLOB NOT NULL CHECK (length(bytes) <= 262144),
  PRIMARY KEY (app, hash)
);
